//! Original playful synthesized cues, generated by scripts/generate-sounds.py.
//! Embed PCM playback copies; the generator can recreate masters in .tmp/sounds.
#[cfg(any(windows, test))]
use crate::domain::*;

pub const VERSION: &str = "v7";
#[cfg(test)]
const EVENTS: [&str; 5] = [
    "started",
    "stopped",
    "canceled",
    "transcribed",
    "transformed",
];

#[cfg(any(windows, test))]
pub(crate) fn asset(event: &str) -> Result<&'static [u8]> {
    match event {
        "started" => Ok(include_bytes!("../../assets/sounds/runtime/started.wav")),
        "stopped" => Ok(include_bytes!("../../assets/sounds/runtime/stopped.wav")),
        "canceled" => Ok(include_bytes!("../../assets/sounds/runtime/canceled.wav")),
        "transcribed" => Ok(include_bytes!(
            "../../assets/sounds/runtime/transcribed.wav"
        )),
        "transformed" => Ok(include_bytes!(
            "../../assets/sounds/runtime/transformed.wav"
        )),
        _ => Err(AppError::input("Unknown event sound.")),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cues_have_distinct_durations_audible_energy_and_no_clipping() {
        let mut lengths = std::collections::BTreeSet::new();
        for (event, frames) in EVENTS.into_iter().zip([19200, 15840, 15360, 21120, 16800]) {
            let mut reader =
                hound::WavReader::new(std::io::Cursor::new(asset(event).unwrap())).unwrap();
            assert_eq!(reader.spec().sample_rate, 48000);
            assert_eq!(reader.spec().channels, 1);
            assert_eq!(reader.spec().bits_per_sample, 16);
            let audio: Vec<i16> = reader.samples().map(|s| s.unwrap()).collect();
            assert_eq!(audio.len(), frames);
            assert!(lengths.insert(audio.len()));
            let peak = audio.iter().map(|v| v.unsigned_abs()).max().unwrap();
            let rms = (audio.iter().map(|v| (*v as f64).powi(2)).sum::<f64>() / audio.len() as f64)
                .sqrt();
            assert!(peak > 3000 && peak < 24000);
            assert!(rms > 500.);
            assert_eq!(audio[0], 0);
            assert_eq!(*audio.last().unwrap(), 0);
        }
        assert!(asset("invalid").is_err());
    }
}
